static inline int fpm_spinlock(atomic_t *lock, int try_once) /* {{{ */ /* <=== fpm_spinlock */ 
{
	if (try_once) {
		return atomic_cmp_set(lock, 0, 1) ? 1 : 0;
	}

	for (;;) {

		if (atomic_cmp_set(lock, 0, 1)) {
			break;
		}

		sched_yield();
	}

	return 1;
}

